from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(1, 0, 0), 'fixture 1'
assert solve([], 1) == Report(1, 0, 0), 'fixture 2'
assert solve([Entry(0, 1, 2)], 2) == Report(2, 2, 2), 'fixture 3'
assert solve([Entry(1, 2, 6), Entry(1, 2, 1)], 3) == Report(1, 0, 0), 'fixture 4'
assert solve([Entry(0, 3, 1), Entry(0, 3, 4), Entry(0, 2, 3)], 4) == Report(3, 4, 3), 'fixture 5'
assert solve([Entry(2, 3, 4), Entry(0, 2, 4), Entry(2, 3, 5), Entry(2, 3, 4)], 5) == Report(3, 12, 8), 'fixture 6'
assert solve([Entry(0, 2, 3), Entry(0, 4, 5), Entry(1, 2, 7), Entry(4, 5, 6), Entry(4, 5, 4)], 6) == Report(4, 17, 9), 'fixture 7'
assert solve([Entry(0, 6, 4), Entry(4, 5, 5), Entry(0, 2, 3), Entry(0, 4, 2), Entry(0, 1, 6), Entry(3, 5, 6)], 7) == Report(6, 22, 7), 'fixture 8'
assert solve([Entry(3, 4, 5), Entry(3, 5, 3), Entry(6, 7, 1), Entry(2, 4, 6), Entry(3, 5, 6), Entry(6, 7, 7), Entry(3, 4, 7)], 8) == Report(1, 0, 0), 'fixture 9'
assert solve([Entry(0, 1, 7), Entry(0, 1, 4), Entry(0, 1, 7), Entry(0, 1, 7), Entry(0, 1, 6), Entry(0, 1, 7), Entry(0, 1, 4), Entry(0, 1, 3), Entry(0, 1, 4)], 2) == Report(2, 3, 3), 'fixture 10'
assert solve([Entry(0, 1, 3), Entry(0, 2, 1), Entry(1, 2, 2), Entry(0, 1, 4), Entry(0, 1, 2), Entry(0, 1, 6), Entry(0, 2, 4), Entry(1, 2, 3), Entry(1, 2, 3), Entry(0, 1, 1)], 3) == Report(3, 2, 1), 'fixture 11'
assert solve([Entry(1, 2, 3), Entry(2, 3, 5), Entry(1, 3, 1), Entry(0, 3, 6), Entry(1, 3, 2), Entry(2, 3, 3), Entry(0, 3, 4), Entry(0, 1, 5), Entry(2, 3, 7), Entry(2, 3, 2), Entry(1, 2, 7)], 4) == Report(4, 17, 8), 'fixture 12'
assert solve([Entry(1, 4, 2), Entry(3, 4, 6), Entry(2, 4, 3), Entry(2, 3, 2), Entry(0, 3, 2), Entry(1, 3, 2), Entry(1, 4, 1), Entry(1, 2, 7), Entry(3, 4, 1), Entry(3, 4, 2), Entry(0, 4, 1), Entry(3, 4, 6)], 5) == Report(3, 3, 2), 'fixture 13'
assert solve([], 6) == Report(1, 0, 0), 'fixture 14'
assert solve([Entry(2, 3, 2)], 7) == Report(1, 0, 0), 'fixture 15'
assert solve([Entry(3, 4, 4), Entry(3, 5, 3)], 8) == Report(1, 0, 0), 'fixture 16'
assert solve([Entry(0, 1, 4), Entry(0, 1, 1), Entry(0, 1, 2), Entry(0, 1, 5)], 2) == Report(2, 1, 1), 'fixture 17'
assert solve([Entry(1, 2, 3), Entry(1, 2, 1), Entry(0, 2, 4), Entry(1, 2, 7), Entry(1, 2, 5)], 3) == Report(2, 4, 4), 'fixture 18'
assert solve([Entry(0, 1, 3), Entry(1, 2, 2), Entry(1, 3, 3), Entry(2, 3, 5), Entry(2, 3, 5), Entry(2, 3, 2)], 4) == Report(4, 14, 6), 'fixture 19'
assert solve([Entry(1, 2, 2), Entry(2, 3, 6), Entry(1, 3, 5), Entry(0, 2, 1), Entry(0, 1, 4), Entry(2, 3, 2), Entry(1, 4, 1)], 5) == Report(5, 13, 5), 'fixture 20'
assert solve([Entry(2, 3, 2), Entry(0, 3, 2), Entry(1, 3, 3), Entry(2, 5, 4), Entry(0, 2, 5), Entry(3, 5, 1), Entry(2, 5, 2), Entry(0, 5, 5)], 6) == Report(4, 10, 5), 'fixture 21'
assert solve([Entry(0, 1, 9), Entry(0, 1, 3), Entry(1, 3, 5), Entry(2, 3, 1), Entry(0, 3, 12)], 5) == Report(3, 11, 8), 'fixture 22'
assert solve([Entry(0, 1, 8), Entry(0, 2, 2), Entry(1, 3, 1), Entry(2, 3, 3)], 5) == Report(4, 15, 8), 'fixture 23'
